// ── Offline pack bundles (`.yizpack`) — add-offline-pack-supply ─────────────
//
// One printable, copyable file that makes a pack installable with no network.
// The marketplace manifest ALREADY embeds every skill body (installPack reads
// skill.content / skill.files straight off the manifest), so the bundle is a
// manifest SNAPSHOT plus the integrity metadata that makes tampering loud:
//
//   bundle.json    {formatVersion, packId, version, origin?, files:[{path,sha256,bytes}]}
//   manifest.json  byte-equal to the market's response for that version
//   files/…        OPTIONAL extra artefacts referenced by a future manifest
//                  shape; v1 requires none (nothing is external today)
//
// Integrity discipline: every listed file is sha256-checked on read; any
// mismatch rejects the WHOLE bundle (no half install). Zip entries are
// validated against path traversal, absolute paths, duplicates and a size /
// count cap before anything is trusted.
//
// Determinism: entry order is sorted and every zip date is pinned to the zip
// epoch, so exporting the same pack version twice yields an identical file.

import crypto from "node:crypto";
import JSZip from "jszip";

export const BUNDLE_FORMAT_VERSION = 1;
export const BUNDLE_EXT = ".yizpack";

// Caps sized for the largest real packs (skill trees with scripts), not for
// arbitrary uploads: the import endpoint is a local management surface.
export const BUNDLE_LIMITS = {
  maxBytes: 64 * 1024 * 1024,
  maxFiles: 2000,
  maxPathLen: 240,
};

// The zip epoch — 1980-01-01. Pinning every entry to it is what makes the
// generated bytes reproducible across runs (JSZip otherwise stamps "now").
const ZIP_EPOCH = new Date(Date.UTC(1980, 0, 1, 0, 0, 0));

function sha256(buf) {
  return crypto.createHash("sha256").update(buf).digest("hex");
}

function bundleError(message, code, extra = {}) {
  return Object.assign(new Error(message), { status: 400, code, ...extra });
}

// Reject anything that could escape the extract root or collide: absolute
// paths, drive letters, backslashes, `..` segments, empty segments, NUL bytes.
//
// Exported for direct testing: the zip library normalizes `../` on the way IN
// (it rewrites `../escape.txt` to `escape.txt`), so the traversal case is
// asserted here rather than through a container. Absolute paths DO survive
// the library, so the zip-level test covers that one.
export function assertSafePath(p) {
  const path = String(p ?? "");
  if (!path || path.length > BUNDLE_LIMITS.maxPathLen) {
    throw bundleError(`bundle entry path is empty or too long: ${path.slice(0, 80)}`, "bundle_bad_path");
  }
  if (path.includes("\0") || path.includes("\\")) {
    throw bundleError(`bundle entry path carries an illegal character: ${path}`, "bundle_bad_path");
  }
  if (path.startsWith("/") || /^[A-Za-z]:/.test(path)) {
    throw bundleError(`bundle entry path is absolute: ${path}`, "bundle_bad_path");
  }
  const parts = path.split("/");
  if (parts.some((seg) => seg === "" || seg === "." || seg === "..")) {
    throw bundleError(`bundle entry path traverses: ${path}`, "bundle_bad_path");
  }
  return path;
}

export function bundleFileName(packId, version) {
  return `${String(packId).replace(/[^A-Za-z0-9._-]+/g, "-")}-v${version}${BUNDLE_EXT}`;
}

// Build the bundle bytes. `files` maps a relative path → string|Buffer for the
// OPTIONAL extra artefacts; the manifest itself travels as manifest.json.
export async function buildBundle({ packId, version, manifest, files = {}, origin = null }) {
  if (!packId || !manifest?.name || !Number.isInteger(Number(version))) {
    throw bundleError("packId, version and manifest are required", "bundle_bad_input");
  }
  const manifestBuf = Buffer.from(`${JSON.stringify(manifest, null, 2)}\n`, "utf8");
  const entries = [{ path: "manifest.json", buf: manifestBuf }];
  for (const [rawPath, value] of Object.entries(files)) {
    const path = assertSafePath(`files/${String(rawPath)}`);
    entries.push({ path, buf: Buffer.isBuffer(value) ? value : Buffer.from(String(value), "utf8") });
  }
  entries.sort((a, b) => a.path.localeCompare(b.path));

  const meta = {
    formatVersion: BUNDLE_FORMAT_VERSION,
    packId: String(packId),
    version: Number(version),
    ...(origin ? { origin: String(origin).slice(0, 500) } : {}),
    files: entries.map((e) => ({ path: e.path, sha256: sha256(e.buf), bytes: e.buf.length })),
  };
  const metaBuf = Buffer.from(`${JSON.stringify(meta, null, 2)}\n`, "utf8");

  const zip = new JSZip();
  zip.file("bundle.json", metaBuf, { date: ZIP_EPOCH, createFolders: false });
  for (const e of entries) zip.file(e.path, e.buf, { date: ZIP_EPOCH, createFolders: false });
  return zip.generateAsync({ type: "nodebuffer", compression: "DEFLATE", compressionOptions: { level: 6 } });
}

// Read + verify a bundle. Throws a structured error (status 400 + code) on any
// integrity or shape violation — callers surface it, never repair silently.
export async function readBundle(buffer, { limits = BUNDLE_LIMITS } = {}) {
  if (!Buffer.isBuffer(buffer) || buffer.length === 0) {
    throw bundleError("bundle is empty", "bundle_empty");
  }
  if (buffer.length > limits.maxBytes) {
    throw bundleError(`bundle exceeds ${limits.maxBytes} bytes`, "bundle_too_large");
  }

  let zip;
  try {
    zip = await JSZip.loadAsync(buffer, { checkCRC32: true });
  } catch (e) {
    throw bundleError(`bundle is not a readable zip: ${e?.message || e}`, "bundle_unreadable");
  }

  const names = Object.keys(zip.files).filter((n) => !zip.files[n].dir);
  if (names.length === 0) throw bundleError("bundle has no files", "bundle_empty");
  if (names.length > limits.maxFiles) {
    throw bundleError(`bundle carries more than ${limits.maxFiles} entries`, "bundle_too_many_files");
  }
  for (const name of names) assertSafePath(name);

  if (!zip.files["bundle.json"]) throw bundleError("bundle.json is missing", "bundle_meta_missing");
  if (!zip.files["manifest.json"]) throw bundleError("manifest.json is missing", "bundle_manifest_missing");

  let meta;
  try {
    meta = JSON.parse(await zip.files["bundle.json"].async("string"));
  } catch (e) {
    throw bundleError(`bundle.json is not valid JSON: ${e?.message || e}`, "bundle_meta_invalid");
  }
  if (Number(meta?.formatVersion) !== BUNDLE_FORMAT_VERSION) {
    throw bundleError(`unsupported bundle formatVersion ${meta?.formatVersion}`, "bundle_format_unsupported");
  }
  if (!meta.packId || !Number.isInteger(Number(meta.version)) || !Array.isArray(meta.files)) {
    throw bundleError("bundle.json is missing packId/version/files", "bundle_meta_invalid");
  }

  // The digest list is the whole-bundle gate: every listed file must exist and
  // match, and nothing unlisted may ride along.
  const listed = new Map();
  for (const entry of meta.files) {
    const path = assertSafePath(entry?.path);
    if (listed.has(path)) throw bundleError(`bundle.json lists ${path} twice`, "bundle_meta_invalid");
    listed.set(path, entry);
  }
  const extras = names.filter((n) => n !== "bundle.json" && !listed.has(n));
  if (extras.length > 0) {
    throw bundleError(`bundle carries unlisted entries: ${extras.slice(0, 5).join(", ")}`, "bundle_unlisted_entry");
  }

  const files = {};
  for (const [path, entry] of listed) {
    const node = zip.files[path];
    if (!node) throw bundleError(`bundle.json lists a missing file: ${path}`, "bundle_file_missing", { path });
    const buf = await node.async("nodebuffer");
    if (Number(entry.bytes) !== buf.length || entry.sha256 !== sha256(buf)) {
      throw bundleError(`bundle file failed its digest check: ${path}`, "bundle_digest_mismatch", { path });
    }
    files[path] = buf;
  }

  let manifest;
  try {
    manifest = JSON.parse(files["manifest.json"].toString("utf8"));
  } catch (e) {
    throw bundleError(`manifest.json is not valid JSON: ${e?.message || e}`, "bundle_manifest_invalid");
  }

  return {
    meta: { ...meta, packId: String(meta.packId), version: Number(meta.version) },
    manifest,
    files: Object.fromEntries(Object.entries(files).filter(([p]) => p !== "manifest.json")),
  };
}

// Serialize for JSON transport (the browser/CLI may post base64 instead of raw
// bytes; the global JSON parser owns /api/mypacks).
export function toBase64(buf) {
  return Buffer.from(buf).toString("base64");
}

export function fromBase64(text) {
  const raw = String(text ?? "").trim();
  if (!raw) throw bundleError("bundle payload is empty", "bundle_empty");
  // Accept a data: URL prefix from browser file readers.
  const body = raw.startsWith("data:") ? raw.slice(raw.indexOf(",") + 1) : raw;
  try {
    return Buffer.from(body, "base64");
  } catch (e) {
    throw bundleError(`bundle payload is not valid base64: ${e?.message || e}`, "bundle_bad_base64");
  }
}
